const lessons=[{"sentences":[{"speaker":"A","text":"Attention all hotel guests because our main shuttle service schedule changes starting tomorrow morning.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.11325},{"speaker":"A","text":"The yellow bus will depart every twenty minutes instead of every half hour from the main lobby.","position":2,"audioStartSeconds":6.31325,"audioEndSeconds":11.958333333333334},{"speaker":"A","text":"If you booked an early morning tour you should meet the driver outside the east entrance.","position":3,"audioStartSeconds":12.158333333333333,"audioEndSeconds":17.184125},{"speaker":"A","text":"Please collect your updated timetables at the front desk before heading out to your destinations.","position":4,"audioStartSeconds":17.384125,"audioEndSeconds":23.311958333333333},{"speaker":"A","text":"We apologize for any temporary inconvenience although these adjustments improve overall transit reliability.","position":5,"audioStartSeconds":23.511958333333332,"audioEndSeconds":30.3805},{"speaker":"A","text":"Speak with concierge staff if you require private transportation during peak afternoon hours.","position":6,"audioStartSeconds":30.5805,"audioEndSeconds":36.44391666666667},{"speaker":"A","text":"Thank you for choosing our property and have a wonderful stay with us today.","position":7,"audioStartSeconds":36.64391666666667,"audioEndSeconds":41.07691666666667},{"speaker":"A","text":"Welcome arriving passengers to the regional airport transportation desk located near terminal two.","role":"section-start","position":8,"audioStartSeconds":46.07691666666667,"audioEndSeconds":52.391333333333336},{"speaker":"A","text":"Your reserved rental vehicles await you on the lower level parking garage section three.","position":9,"audioStartSeconds":52.59133333333333,"audioEndSeconds":57.82329166666667},{"speaker":"A","text":"When you complete your paperwork at our counter please present your valid driver license.","position":10,"audioStartSeconds":58.023291666666665,"audioEndSeconds":63.29391666666667},{"speaker":"A","text":"An attendant wearing a bright orange vest will guide you directly to your automobile.","position":11,"audioStartSeconds":63.493916666666664,"audioEndSeconds":68.63566666666667},{"speaker":"A","text":"Should your checked baggage experience any delay notify our service desk immediately for assistance.","position":12,"audioStartSeconds":68.83566666666667,"audioEndSeconds":74.86658333333334},{"speaker":"A","text":"Travelers heading downtown can also purchase discounted subway passes right here at this window.","position":13,"audioStartSeconds":75.06658333333333,"audioEndSeconds":81.16195833333333},{"speaker":"A","text":"We wish you a very safe and pleasant journey onward to your final destinations.","position":14,"audioStartSeconds":81.36195833333333,"audioEndSeconds":86.44875}],"questions":[{"prompt":"What is changing about the shuttle service starting tomorrow?","options":["It will stop running entirely.","It will run more frequently.","It will depart from a new station."],"answer":"B","evidenceSentence":2,"evidence":"depart every twenty minutes instead of every half hour","explanation":"Thông báo nêu rõ xe buýt sẽ khởi hành cứ sau hai mươi phút thay vì nửa giờ, nghĩa là tần suất chạy thường xuyên hơn."},{"prompt":"Where should guests participating in an early morning tour gather?","options":["Outside the east entrance.","Inside the main lobby.","At the front desk."],"answer":"A","evidenceSentence":3,"evidence":"meet the driver outside the east entrance","explanation":"Người nói hướng dẫn những ai đặt tour sáng sớm hãy gặp tài xế ở bên ngoài lối vào phía đông."},{"prompt":"What are guests advised to pick up at the front desk?","options":["Tour tickets.","Updated timetables.","Room keys."],"answer":"B","evidenceSentence":4,"evidence":"collect your updated timetables at the front desk","explanation":"Khách được yêu cầu nhận lịch trình thời gian đã cập nhật tại quầy lễ tân trước khi đi."},{"prompt":"Where is the airport transportation desk situated?","options":["Near terminal two.","On the parking garage roof.","Inside the downtown subway station."],"answer":"A","evidenceSentence":8,"evidence":"located near terminal two","explanation":"Bàn dịch vụ vận chuyển tại sân bay nằm ở khu vực gần nhà ga số hai."},{"prompt":"What document must passengers show when completing their paperwork?","options":["A hotel reservation card.","A valid driver license.","A subway pass."],"answer":"B","evidenceSentence":10,"evidence":"present your valid driver license","explanation":"Hành khách cần xuất trình giấy phép lái xe hợp lệ khi hoàn thành thủ tục tại quầy."},{"prompt":"What extra item can travelers buy at the transportation window?","options":["Discounted subway passes.","Early morning tour tickets.","Orange vests."],"answer":"A","evidenceSentence":13,"evidence":"purchase discounted subway passes right here","explanation":"Hành khách đi trung tâm thành phố có thể mua vé tàu điện ngầm giảm giá ngay tại cửa sổ này."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
